function validateStructuredActivity(raw){return !!window.ActivityContract?.validate(raw).ok;}

const normalizedActivities=[];
for(const raw of structuredActivities){
  const check=window.ActivityContract.validate(raw);
  if(check.ok){normalizedActivities.push(check.activity);window.SakhiRuntimeLog?.log('ACTIVITY_VALIDATED',{activity_id:check.activity.activity_id,interaction_type:check.activity.interaction_type});}
  else{window.SakhiRuntimeLog?.log('ACTIVITY_SCHEMA_INVALID',{activity_id:raw.id,errors:check.errors});const fallback=window.ActivityContract.fallbackFor(raw,structuredActivities);if(fallback)normalizedActivities.push(fallback);}
}
activities.splice(0,activities.length,...normalizedActivities);
