function setupTraceCanvas(a){const c=document.getElementById('traceCanvas'),ctx=c.getContext('2d'),pts=traceScale(a,c);runtimeState().guidePoints=pts;runtimeState().tracePoints=[];ctx.clearRect(0,0,c.width,c.height);ctx.lineWidth=20;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#e5d7f4';ctx.setLineDash([5,12]);ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#ffd84d';ctx.beginPath();ctx.arc(pts[0][0],pts[0][1],13,0,Math.PI*2);ctx.fill();let drawing=false,last=null;const pos=e=>{const r=c.getBoundingClientRect();return[(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};c.onpointerdown=e=>{if(actionPulse())return;drawing=true;last=pos(e);runtimeState().tracePoints.push(last);c.setPointerCapture?.(e.pointerId)};c.onpointermove=e=>{if(!drawing)return;const p=pos(e);ctx.strokeStyle='#8f56dd';ctx.lineWidth=10;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(...last);ctx.lineTo(...p);ctx.stroke();last=p;runtimeState().tracePoints.push(p)};c.onpointerup=()=>{drawing=false;updateTraceQuality(a)};c.onpointercancel=()=>drawing=false;}
function traceMetrics(a){const drawn=runtimeState().tracePoints||[],guide=runtimeState().guidePoints||[];if(!drawn.length||!guide.length)return {coverage:0,avgDeviation:Infinity,startOk:false};let covered=0,totalDev=0;for(const g of guide){let best=Infinity;for(const p of drawn){const d=Math.hypot(g[0]-p[0],g[1]-p[1]);if(d<best)best=d;}if(best<=a.stroke_tolerance)covered++;totalDev+=best;}const startDist=Math.hypot(guide[0][0]-drawn[0][0],guide[0][1]-drawn[0][1]);return {coverage:covered/guide.length,avgDeviation:totalDev/guide.length,startOk:startDist<=a.stroke_tolerance*1.6};}
