function renderOffline(a,m){m.innerHTML=`<div class="offline-card"><div class="offline-icon">${a.interaction_type==='movement'?'🏃‍♀️':'🏡'}</div><p>${esc(a.spoken_instruction)}</p></div><div class="rating"><button type="button" onclick="finishParentRated(1)">✨ I did it!</button><button type="button" onclick="finishParentRated(.65)">🤝 With help</button><button type="button" onclick="finishParentRated(.2)">🌱 Not yet</button></div>`;}
