function handleRetry(allowHint=true){if(!interactionRuntime||interactionRuntime.saving)return;const r=interactionRuntime,a=r.activity;const f=document.getElementById('structuredFeedback');if(f)f.textContent='🌈 '+a.retry_feedback;logEvent('ACTIVITY_RETRY');if(r.attempts>=2&&allowHint&&r.hintLevel<2)showHint();if(r.attempts>=3){r.hintLevel=3;const h=document.getElementById('structuredHint');if(h)h.textContent='💡 '+a.hint_3;document.getElementById('interactionMount')?.classList.add('strong-scaffold');}}
